reversal.fixed_text:
MatchType::DfaAnchoredReverse => {
    match dfa::Fsm::reverse(
        &self.ro.dfa_reverse,
        self.cache.value(),
        true,
        &text[start..],
        text.len() - start,
    ) {
        dfa::Result::Match(_) => Some(text.len()),
        dfa::Result::NoMatch(_) => None,
        dfa::Result::Quit => self.shortest_nfa(text, start),
    }
}

